mapper.select:
SELECT
    ts,event_ts,point_id,point_code,point_name,value_text,value_double,value_long,value_bool,quality,success,message,raw_json,processed_json,metadata_json
FROM ${database}.${subTable}
WHERE 1 = 1

    AND point_id = #{pointId}


    AND ts >= #{startTs}


    AND ts <= #{endTs}

ORDER BY ts DESC
LIMIT #{limit}
